mapper.update:
update biz_visit set status = '3', update_by = #{phone}, update_time = sysdate()
where visit_id = #{visitId} and visitor_phone = #{phone} and tenant_id = #{tenantId}
  and status in ('0', '1')

mapper.select:
select family_id, family_name, phone, relation, elder_id, status, tenant_id, create_time
from biz_family
where phone = #{phone} and elder_id = #{elderId} and tenant_id = #{tenantId}
